-- EcoMate SaaS tenant isolation: RLS policies + write guards.
-- Generated by scripts/saas/generate_rls.py from schema.tenant.prisma.
--
-- This migration does NOT create a login role with a password.
-- The deployment provisioner creates `ecomate_app` (NOSUPERUSER,
-- NOBYPASSRLS) and sets its credentials out of band. Migrations and
-- controlled backfills run as the owner/migrator role.

BEGIN;

-- The current tenant is carried on the connection by the tenant pool:
--   options = '-c app.tenant_id=<tenant-uuid>'
-- An unset/empty setting makes both reads and writes fail closed.
CREATE OR REPLACE FUNCTION enforce_tenant_id() RETURNS trigger AS $$
DECLARE
  ctx text;
BEGIN
  ctx := NULLIF(current_setting('app.tenant_id', true), '');
  IF ctx IS NULL OR ctx = '' THEN
    RAISE EXCEPTION 'tenant context missing';
  END IF;
  NEW.tenant_id := ctx::uuid;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'ecomate_app') THEN
    CREATE ROLE ecomate_app NOLOGIN NOSUPERUSER NOBYPASSRLS;
  END IF;
  EXECUTE 'GRANT USAGE ON SCHEMA public TO ecomate_app';
  EXECUTE 'GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO ecomate_app';
  EXECUTE 'GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO ecomate_app';
  EXECUTE 'ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO ecomate_app';
  EXECUTE 'ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT USAGE, SELECT ON SEQUENCES TO ecomate_app';
END $$;

-- AccessPreset -> AccessPreset
ALTER TABLE "AccessPreset" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "AccessPreset" FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_isolation ON "AccessPreset";
CREATE POLICY tenant_isolation ON "AccessPreset"
  USING (tenant_id = (NULLIF(current_setting('app.tenant_id', true), ''))::uuid)
  WITH CHECK (tenant_id = (NULLIF(current_setting('app.tenant_id', true), ''))::uuid);
DROP TRIGGER IF EXISTS tenant_id_guard ON "AccessPreset";
CREATE TRIGGER tenant_id_guard BEFORE INSERT OR UPDATE ON "AccessPreset"
  FOR EACH ROW EXECUTE FUNCTION enforce_tenant_id();

