-- RLS coverage view used by CI and the boot-time check.
-- A row with tenant_scoped=true and any of rls_enabled/rls_forced/
-- has_policy/has_trigger false is a deployment-blocking gap.
CREATE OR REPLACE VIEW rls_coverage AS
SELECT c.relname AS table_name,
       EXISTS (SELECT 1 FROM information_schema.columns col
               WHERE col.table_schema = 'public'
                 AND col.table_name = c.relname
                 AND col.column_name = 'tenant_id') AS tenant_scoped,
       c.relrowsecurity AS rls_enabled,
       c.relforcerowsecurity AS rls_forced,
       EXISTS (SELECT 1 FROM pg_policies p
               WHERE p.schemaname = 'public'
                 AND p.tablename = c.relname
                 AND p.policyname = 'tenant_isolation') AS has_policy,
       EXISTS (SELECT 1 FROM pg_trigger t
               WHERE t.tgrelid = c.oid
                 AND t.tgname = 'tenant_id_guard'
                 AND NOT t.tgisinternal) AS has_trigger
FROM pg_class c
JOIN pg_namespace n ON n.oid = c.relnamespace
WHERE n.nspname = 'public'
  AND c.relkind = 'r'
  AND c.relname <> '_prisma_migrations';

COMMIT;
